dashboard.definition:
{
    "title": "AI Workload Infrastructure",
    "description": "AI workload: network to DC, AI support bot, Cisco AI Defense, GPU cluster and the support hotline",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-60m@m,now"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_chain": {
            "type": "ds.search",
            "options": {
                "query": "(index=demo_thousendeyes sourcetype=\"thousendeyes:json\" ((thousandeyes.test.type=agent-to-agent thousandeyes.target.agent.location=frankfurt) OR \"thousandeyes.test.name\"=\"AI Support Assistant API\")) OR (index=demo_ai_defense sourcetype=\"cisco:ai:defense\") OR (index=demo_msteams event_type=call_queue_stats queue_name=\"Support Hotline\")\n| eval loss=if('thousandeyes.test.type'=\"agent-to-agent\", 'metric_name:network.loss', null()), duration=if('thousandeyes.test.name'=\"AI Support Assistant API\", 'metric_name:api.duration', null())\n| stats avg(loss) as loss avg(duration) as duration count(eval(event_message_type=\"prompt\" AND event_action=\"Allow\")) as prompts count(eval(event_message_type=\"response\")) as responses latest(calls_waiting) as waiting\n| appendcols [| mstats avg(_value) as aborted WHERE index=demo_vmware_metrics metric_name=\"vmware.vm.gpu.llm.requests.aborted.pct\" location=\"frankfurt\" earliest=-5m latest=now]\n| eval unanswered=if(prompts > 0, round(100 * (prompts - responses) / prompts, 1), null())\n| eval r=mvappend(\"Network to DC;network;\".if(isnull(loss), \"none\", case(loss>=5, \"crit\", loss>=1, \"warn\", true(), \"ok\")).\";\".coalesce(\"loss \".round(loss, 1).\" %\", \"no data\"), \"AI Support Bot;bot;\".if(isnull(duration), \"none\", case(duration>=6, \"crit\", duration>=3, \"warn\", true(), \"ok\")).\";\".coalesce(round(duration, 1).\" s response\", \"no data\"), \"AI Defense;shield;\".if(isnull(unanswered), \"none\", case(unanswered>=20, \"crit\", unanswered>=5, \"warn\", true(), \"ok\")).\";\".coalesce(unanswered.\" % unanswered\", \"no data\"), \"GPU Cluster;gpu;\".if(isnull(aborted), \"none\", case(aborted>=20, \"crit\", aborted>=5, \"warn\", true(), \"ok\")).\";\".coalesce(round(aborted, 0).\" % aborted\", \"no data\"), \"Support Hotline;phone;\".if(isnull(waiting), \"none\", case(waiting>=12, \"crit\", waiting>=4, \"warn\", true(), \"ok\")).\";\".coalesce(waiting.\" calls waiting\", \"no data\"))\n| mvexpand r\n| eval f=split(r, \";\"), stage=mvindex(f, 0), icon=mvindex(f, 1), status=mvindex(f, 2), metric=mvindex(f, 3)\n| table stage icon status metric",
                "enableSmartSources": true,
                "queryParameters": {
                    "earliest": "-5m",
                    "latest": "now"
                },
                "refresh": "1m",
                "refreshType": "delay"
            },
            "name": "AI support chain (live)"
        },
        "ds_te": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_thousendeyes sourcetype=\"thousendeyes:json\" ((thousandeyes.test.type=agent-to-agent thousandeyes.target.agent.location=frankfurt) OR \"thousandeyes.test.name\"=\"AI Support Assistant API\")\n| eval kind=if('thousandeyes.test.type'=\"agent-to-agent\", \"loss\", \"bot\"), v=if(kind=\"loss\", 'metric_name:network.loss', 'metric_name:api.duration'), plant='thousandeyes.agent.location'\n| bin _time span=1m\n| stats avg(v) as v by _time kind plant",
                "enableSmartSources": true
            },
            "name": "ThousandEyes plant to DC (1 min)"
        },
        "ds_loss": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_te",
                "query": "| where kind=\"loss\" | timechart span=1m avg(v) by plant"
            }
        },
        "ds_bot": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_te",
                "query": "| where kind=\"bot\" | timechart span=1m avg(v) by plant"
            }
        },
        "ds_k_loss": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_te",
                "query": "| where kind=\"loss\" | timechart span=1m avg(v) as \"Loss to DC\""
            }
        },
        "ds_k_bot": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_te",
                "query": "| where kind=\"bot\" | timechart span=1m avg(v) as \"Bot response\""
            }
        },
        "ds_aid": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_ai_defense sourcetype=\"cisco:ai:defense\"\n| eval message=if(event_message_type=\"prompt\", \"Prompts\", \"Responses\")\n| timechart span=1m count by message",
                "enableSmartSources": true
            },
            "name": "AI Defense prompts and responses"
        },
        "ds_k_unanswered": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_aid",
                "query": "| eval \"Unanswered\"=if(Prompts > 0, round(100 * (Prompts - Responses) / Prompts, 1), null()) | fields _time Unanswered"
            }
        },
        "ds_guard": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_ai_defense sourcetype=\"cisco:ai:defense\" \"event_policy_guardrail_assocs{}.policy_guardrail_assoc.guardrail_avail_entity.guardrail_entity_name\"=*\n| rename \"event_policy_guardrail_assocs{}.policy_guardrail_assoc.guardrail_avail_entity.guardrail_entity_name\" as Guardrail\n| stats count as Hits by Guardrail event_action event_message_type\n| rename event_action as Action event_message_type as Direction\n| sort - Hits",
                "enableSmartSources": true
            },
            "name": "Guardrail hits"
        },
        "ds_gpu": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as value WHERE index=demo_vmware_metrics location=\"frankfurt\" metric_name IN (\"vmware.vm.gpu.utilization.pct\", \"vmware.vm.gpu.llm.requests.aborted.pct\", \"vmware.vm.gpu.llm.ttft.ms\") BY metric_name span=1m\n| eval metric=case(metric_name=\"vmware.vm.gpu.utilization.pct\", \"GPU utilization %\", metric_name=\"vmware.vm.gpu.llm.requests.aborted.pct\", \"Aborted requests %\", true(), \"Time to first token ms\")",
                "enableSmartSources": true
            },
            "name": "GPU cluster Frankfurt (1 min)"
        },
        "ds_gpu_chart": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_gpu",
                "query": "| where metric!=\"Time to first token ms\" | timechart span=1m avg(value) by metric"
            }
        },
        "ds_ttft": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_gpu",
                "query": "| where metric=\"Time to first token ms\" | timechart span=1m avg(value) as \"Time to first token\""
            }
        },
        "ds_k_gpu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_gpu",
                "query": "| where metric=\"GPU utilization %\" | timechart span=1m avg(value) as \"GPU utilization\""
            }
        },
        "ds_k_aborted": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_gpu",
                "query": "| where metric=\"Aborted requests %\" | timechart span=1m avg(value) as \"Aborted\""
            }
        },
        "ds_hotline": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_msteams event_type=call_queue_stats queue_name=\"Support Hotline\"\n| timechart span=1m max(calls_waiting) as \"Calls waiting\" sum(bot_handoffs) as \"Handed over by the bot\" max(agents_available) as \"Agents available\"",
                "enableSmartSources": true
            },
            "name": "Support Hotline queue"
        },
        "ds_k_hotline": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hotline",
                "query": "| fields _time \"Calls waiting\""
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "coolashaker_studio",
                        "dashboard": "cs_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_exec": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/coolashaker_studio/images/nav_exec.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
