            },
            "options": {
                "scaleMode": "thresholds",
                "higherIsBetter": false,
                "warn": 1,
                "crit": 5,
                "unit": "%",
                "decimals": 2
            }
        },
        "viz_09": {
            "type": "splunk.line",
            "dataSources": {
                "primary": "ds_bot"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#22d3ee",
                    "#a78bfa",
                    "#34e2a0",
                    "#ffc53d",
                    "#ff4d6d",
                    "#60a5fa",
                    "#f472b6",
                    "#2dd4bf",
                    "#fb923c",
                    "#e879f9"
                ],
                "seriesColorsByField": {
                    "atlanta": "#22d3ee",
                    "berlin": "#a78bfa",
                    "vienna": "#ffb020",
                    "frankfurt": "#34e2a0",
                    "Atlanta": "#22d3ee",
                    "Berlin": "#a78bfa",
                    "Vienna": "#ffb020",
                    "Frankfurt": "#34e2a0"
                },
