            }
        },
        "viz_14": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_guard"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 6,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                }
            },
            "context": {
                "rowBg": [
                    "#0a1328",
                    "#0d1833"
                ],
                "statusBg": [
                    {
                        "match": "Critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "Degraded",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "Healthy",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "critical",
                        "value": "#5a1426"
                    },
                    {
                        "match": "high",
                        "value": "#5a1426"
                    },
                    {
                        "match": "error",
                        "value": "#5a1426"
                    },
                    {
                        "match": "warning",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "medium",
                        "value": "#4d3a08"
                    },
                    {
                        "match": "stopped",
                        "value": "#5a1426"
                    },
                    {
                        "match": "failed",
                        "value": "#5a1426"
                    },
                    {
                        "match": "running",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "success",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "good",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "normal",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Reachable",
                        "value": "#0d3b2c"
                    },
                    {
                        "match": "Unreachable",
                        "value": "#5a1426"
                    }
                ]
            }
        }
    },
    "layout": {
        "type": "absolute",
        "options": {
            "width": 1920,
            "height": 1920,
            "display": "auto-scale",
